insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-9-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-9'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Relier l''apparition ou la résurgence des formes à leur contexte historique, sociologique, psychologique, philosophique. Montrer comment elles s''y inscrivent, où et en quoi elles sont en rupture. Analyser l''interaction dynamique entre ces différentes composantes et montrer en quoi l''artiste forge, définit, voire remet en question les valeurs et la sensibilité de la culture de telle ou telle société.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-9-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-9'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Identifier un évènement culturel ponctuel et le relier à un ensemble d''activités d''expression.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
