insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Comprendre et appliquer des relations pertinentes entre texte, typographie et image en fonction de l''effet recherché et de la nature du message.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Etre capable de détourner une image ou des signes du sens convenu pour lequel il a été fait et de se l''approprier en lui donnant un sens nouveau, inattendu et signifiant.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Transposer dans un autre registre ou dans une autre technique, déplacer dans un autre domaine de l''expression une première expérience formelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Tirer profit des hasards, convertir les erreurs, subvertir les logiques et utiliser l''inattendu.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Organiser en la classifiant rationnellement une documentation graphique personnelle (chartes et images diverses...) de manière à accroître le champ d''information et d''autonomie créatrice.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Dans la structuration du travail plastique et face à des situations-problèmes, prendre en compte des contraintes externes (cadre, économie des moyens, conventions, consignes, impératifs d''illustration, délais...) ou internes (logique des techniques, volonté personnelle de style ou d''expression).', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-9', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Organiser son travail en fonction d''un projet en y développant des capacités d''initiative.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-12-10', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-12'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Dans le cadre de projets multidisciplinaires, pouvoir défendre ses idées, accepter la discussion, confronter les arguments et, finalement, mener correctement en équipe le projet retenu.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
