insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-13-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-13'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Porter attention à la structure qui sous-tend la forme naturelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
