insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-13-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-13'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Observer dans la perspective de mettre formes et rapports de formes en mémoire afin de pouvoir les restituer en leur absence ou de pouvoir les visualiser intérieurement.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-13-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-13'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Distinguer ce qui relève de la dénotation et de la connotation dans l''approche d''une image ou d''un document pour asseoir l''analyse sur des éléments aussi objectivement reconnus que possible.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-13-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-13'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Percevoir les récurrences formelles qui caractérisent le style d''un artiste ou d''une époque.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-13-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-13'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Dégager autour d''images existantes ou créées par le graphiste des clés pratiques constituant autant d''outils favorisant la créativité (transformer, associer, modifier, transférer, …), développant l''imagination et permettant la communication.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-13-9', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-13'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Exprimer son appréciation sur une œuvre graphique, justifier ses goûts et dégager l''intérêt relatif d''une démarche de communication visuelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Percevoir les récurrences formelles qui caractérisent le style d''un graphiste ou d''une époque.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Décrire l''enchaînement et relier l''apparition ou la résurgence des formes graphiques à leur contexte historique, sociologique, psychologique, philosophique. Montrer comment elles sont en rupture. Analyser l''interaction dynamique entre ces différentes composantes et montrer en quoi l''artiste forge, définit, voire remet en question les valeurs et la sensibilité de la culture de telle ou telle société.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Décrire l''enchaînement et l''évolution de la vie des formes, appliquée en particulier à l''histoire des arts graphiques.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Comparer les œuvres du présent et du passé, dégager des correspondances et les convergences fortuites, déceler les influences, apprécier l''impact d''une œuvre à court et à long terme, prendre conscience des ruptures, donner du sens.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaître les méthodes d''approche sémiologique et linguistique appliquées à la communication graphique (figures et procédés stylistiques, tropes, injonction, redondance, …).', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Tout en proscrivant le jargon, user d''un vocabulaire précis, nuancé et spécifique à l''égard des techniques employées. Assumer de cette façon la richesse du langage professionnel.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Situer les diverses interventions des acteurs de la chaîne graphique l''une par rapport à l''autre (chronologie, procédés, rôles et interférences).', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Comprendre l''esprit et la logique des différents outils, supports et médias en usage dans le domaine de la communication visuelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-9', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaître les règles typographiques essentielles, les impératifs de lisibilité et savoir faire les liaisons entre la typographie et le sens qu''elle véhicule.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-10', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaître de manière critique les principaux ressorts psychologiques agissant à l''intérieur des manifestes publicitaires.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-11', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Apprendre à se documenter et à s''informer, en particulier sur l''évolution des arts graphiques (usage des encyclopédies, des bibliothèques, des tables des matières, des corrélats, des CD-ROM, d''Internet, …)', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-14-12', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-14'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Favoriser la fréquentation directe des œuvres en galerie et au musée afin de les connaître dans leurs vraies dimensions spatiales et sensibles', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Construire le jugement éclairé en structurant la pensée critique (tant vis-à-vis de ses propres réalisations que de celle des autres) et permettre d’échanger ses raisons d’aimer en argumentant. au regard de la représentation ellemême (logique représentative, conformité relative au modèle, réalité perçue ou vécue) ; au regard du « quotient créateur » (puissance transformatrice ou créatrice, originalité de l’apport…), au regard de la clarté de la communication et/ou des possibilités connotatives (ouverture ou fermeture du sens) ; au regard de l’existence plastique de l’œuvre (espace, composition, mise en page, rythme, tension, formes, valeurs, couleurs, textures, proportions, lumière, échelle…), mais aussi dans le rapport de la forme du contenu ; au regard de sa lisibilité et son intelligibilité ; au regard de la norme et du hors norme des codes esthétiques.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Percevoir l’intérêt des démarches mentales et des articulations productrices de sens via les signes graphiques et les images utilisés dans le domaine de la communication visuelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Lire et comprendre le fonctionnement des manifestes visuels existants (aspects sociologiques, sémiologiques, psychologiques…) de manière à en assurer la compréhension et la critique.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Apprécier la richesse de ses racines et de son identité culturelle. Imposer le respect naturel et la valorisation du patrimoine. graphique, justifier ses goûts et dégager l''intérêt relatif d''une démarche de communication visuelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Reconnaître l’autre dans la spécificité de son langage et de ce qu’il est en lisant les production plastiques comme des projections de l’imaginaire et rencontre de l’inconscient, du fonds culturel, des pulsions, des souvenirs, de la créativité, du savoirfaire et des connaissances', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Approcher les arts issus d’autres cultures et milieux sociaux ou religieux. Dégager des relations avec les différentes valeurs, traditions et idéologies.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'S’ouvrir aux expériences esthétiques contemporaines de manières à les intégrer dans sa culture et ses intérêts.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-15-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-15'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Gérer ses choix culturels par confrontations et décodage des moyens de communication actuels (affiche, T.V., radio, cinéma, expositions, spots publicitaires, Internet) en les considérant comme formes.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Construire le jugement éclairé en structurant la pensée critique (tant vis-à-vis de ses propres réalisations que de celle des autres) et permettre d’échanger ses raisons d’aimer en argumentant.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Assurer une relative aisance dans la manipulation de matériel audiovisuel de manière à préparer le travail créatif.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Etablir des rapports visuels (cadrage, lumières, couleurs, contrastes, raccords, profondeur de champ, mouvements du sujet et de la caméra…), temporels (rythmes, longueur et succession de séquences…), sonores (intensité, timbre, coloration, fréquences, mixage…), parlés (dialogue, timbre, respiration…) et narratifs de manière cohérente en les articulant sur une intention formelle ou expressive structurante.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Etablir et pouvoir nuancer ses partis pris formels ou expressifs.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Manipuler et expérimenter les techniques argentines, analogiques et numériques ainsi que la diversité des émulsions et des outils (tout support de traitement de l’image) en les considérants comme des éléments de production et de recherche.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Mettre en corrélation observer, écouter, penser et produire (dans le sens de produire dans un champ d’application audiovisuel), articuler ainsi la forme et le contenu, le geste et le sens, l’outil et la pensée, l’œuvre et le soi.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Prendre en compte des contraintes externes (cadre scolaire et/ou autre, économie des moyens, conventions, consignes, délais…) ou internes (logique des techniques) dans la structuration du travail audiovisuel.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Participer à des projets collectifs ou multidisciplinaires en y apportant son savoir-faire et en se pliant à la discipline qu’impose l’unité globale d’expression ou d’intention qui les justifie.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-9', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Organiser son travail en fonction d’un projet choisi ou imposé en y développant ses capacités d’initiative.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-10', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Pouvoir utiliser les fonctions de base des logiciels les plus courant dans les domaines de la photographie et de l’audiovisuel.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-16-11', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-16'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Développer une curiosité pour l’évolution des nouvelles techniques audiovisuelles, être disponible à se les approprier, s’y adapter et à transférer les acquis potentiels dans l’acte de conception lui-même.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-17-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-17'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Etablir des rapports de grandeur, de position, de correspondance, de rythme, de proportions, de caractère, de couleurs... au sein de documents visuels et audiovisuels.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-17-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-17'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Pouvoir justifier le choix d’un cadrage ou d’une composition relativement à la scène, au document, au thème ou à l’objet observé. Interpréter l’œuvre audiovisuelle comme système de signes dont il convient d’objectiver les relations (forme et expression).', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-17-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-17'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Distinguer ce qui relève de la dénotation et de la connotation dans l’approche d’une image ou d’un document pour pouvoir établir une analyse aussi objective que possible.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-17-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-17'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Percevoir à travers quelques œuvres majeures du cinéma, de la photographie et des productions musicales et audiovisuelles les récurrences formelles qui caractérisent le style d’un metteur en scène, d’un artiste ou d’une époque.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Positionner ses ambitions expressives soit comme tentative de restitution objective de la réalité, soit comme écart entre cette réalité et une manière personnelle de regarder le monde.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Regarder activement le monde extérieur pour donner à voir et/ou à entendre ce qui échappe à la perception commune.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Conférer à l’activité audiovisuelle le statut de lieu de critique et d’écart par rapport à la norme, marquant ainsi la puissance créatrice de l’individu responsable s’identifiant à une création personnelle et « s’écrivant » à travers elle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Dégager des clés pratiques constituant autant d’outils favorisant la créativité (cadrer, monter, éclairer, filtrer, superposer…) et développant l’imagination.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Transposer dans un autre registre visuel, sonore ou audiovisuel, déplacer dans un autre domaine de l’expression une première expérience formelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Pouvoir tirer profit des hasards, convertir les erreurs, utiliser l’inattendu et détourner les choses de leurs fonctions habituelles.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Etre capable de détourner un objet ou une image du sens convenu pour lequel il a été fait et se l’approprier en lui donnant un sens nouveau, inattendu et signifiant.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-18-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-18'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Exprimer son appréciation sur une œuvre audiovisuelle, justifier ses goûts et en dégager l’intérêt relatif.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Dégager les caractères stylistiques essentiels d’une écriture audiovisuelle, d’une époque ou d’un style.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Décrire l’enchaînement et penser à relier l’apparition ou la résurgence des formes d’expression à leur contexte historique et social. Comprendre qu’elles s’y inscrivent, où qu’elles peuvent être en rupture. Apprécier l’interaction dynamique entre ces différentes composantes et en quoi le créateur forge, définit, voire remet en question les valeurs et la sensibilité de la culture de telle ou telle société.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Comparer les œuvres du présent et du passé, dégager des correspondances et les convergences fortuites, déceler les influences, apprécier l’impact d’une œuvre à court et à long terme, prendre conscience des ruptures, donner du sens.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaître les méthodes d’approche sémiologique et sémantique de base appliquées à la communication (figures et procédés stylistiques, tropes, injonction, redondance…)', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Tout en proscrivant le jargon, user d’un vocabulaire précis, nuancé et spécifique à l’égard des techniques employées. Assumer de cette façon la richesse du langage professionnel.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Situer les diverses interventions des acteurs de la production audiovisuelle l’une par rapport à l’autre (chronologie, rôles et interférences).', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Comprendre l’esprit et la logique des différents outils, supports et médias en usage dans le domaine de la communication audiovisuelle.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-8', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaître de manière critique les principaux ressorts psychologiques agissant à l’intérieur des œuvres médiatiques ou audiovisuelles.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-9', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Apprendre à se documenter, à recueillir des témoignages, à recouper son information et à s’informer, en particulier sur l’actualité, l’évolution des médias et des productions audiovisuelles (usage des encyclopédies, des bibliothèques, des médiathèques, des tables des matières, des corrélats, des productions de la presse écrite, des CDROM, d’Internet, des dossiers de presse…)', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-10', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Considérer comme indispensable la fréquentation directe des milieux professionnels, des médiathèques, vidéothèques et cinémathèques, des galeries et musées afin de les connaître dans leurs vraies dimensions spatiales, humaines et sensibles.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-19-11', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-19'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaître les techniques de base des systèmes audiovisuels afin de pouvoir effectuer des choix pratiques judicieux.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Construire le jugement éclairé en structurant la pensée critique (tant vis-à-vis de ses propres réalisations que de celles des autres) et permettre d’échanger ses raisons d’aimer en argumentant : au regard de la logique documentaire ou du reportage qui, là où elle est invoquée, implique une approche objective', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'au regard du « quotient créateur » (puissance transformatrice ou créatrice, originalité de l’apport…)', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'au regard des possibilités connotatives (ouverture ou fermeture du sens)', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-4', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'au regard de l’existence formelle, visuelle et sonore (image, musique, texte, voix…) constitutive de l’œuvre (espace, composition, tension, formes, valeurs, couleurs, textures, proportions, lumières, échelle, mouvement, raccords, temps…), mais aussi dans le rapport de la forme et du contenu', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-5', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'au regard de sa lisibilité et de son intelligibilité, notamment dans la relation aux conditions de production et de réception', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-6', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'au regard de la norme et du hors norme des codes esthétiques.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-20-7', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-20'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Lire et comprendre le fonctionnement des documents audiovisuels existants (presse, annonces, clips vidéos…), de manière à en assurer la compréhension (aspects sociologiques, sémiologiques, psychologiques…) et la critique de même qu’à pouvoir en évaluer l’impact sur le public', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-21-1', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-21'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Lire et utilise les principaux signes du langage musical.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-21-2', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-21'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'S’approprier et utiliser des gestes d’expression musicale et sonore (vocale, instrumentale, corporelle..).', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEA-21-3', (select id from public.curriculum_item where version = '2004' and code = 'CTEA-21'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Intégrer les paramètres sonores dans l’expression vocale et instrumentale.', 'Compétences terminales et savoirs requis en éducation artistique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Artistiqu.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
