insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEPC-2.1.1-C2', (select id from public.curriculum_item where version = '2017' and code = 'CTEPC-2.1.1'), 'secondaire', array['S3', 'S4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Compétence : Repérer les tentatives de manipulation dans les discours', 'Compétences terminales de l''éducation à la philosophie et à la citoyenneté (humanités générales, technologiques, professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Edu-Philo-Citoyen.pdf)', '2017') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEPC-2.1.1-A1', (select id from public.curriculum_item where version = '2017' and code = 'CTEPC-2.1.1'), 'secondaire', array['S3', 'S4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Appliquer : Questionner les stratégies de persuasion d’un discours (textes, images, mise en scène…)', 'Compétences terminales de l''éducation à la philosophie et à la citoyenneté (humanités générales, technologiques, professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Edu-Philo-Citoyen.pdf)', '2017') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEPC-2.1.1-A2', (select id from public.curriculum_item where version = '2017' and code = 'CTEPC-2.1.1'), 'secondaire', array['S3', 'S4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Appliquer : Repérer les présupposés, les préjugés, les sophismes et paralogismes, la langue de bois, les mots mystificateurs ou source d’ambigüités, toute tentative de manipulation ou d’endoctrinement notamment dans les discours politiques, militants, religieux, idéologiques, sectaires… ainsi que dans les discours véhiculés par les médias (presse écrite, parlée, réseaux sociaux, publicité…)', 'Compétences terminales de l''éducation à la philosophie et à la citoyenneté (humanités générales, technologiques, professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Edu-Philo-Citoyen.pdf)', '2017') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTEPC-2.1.1-A3', (select id from public.curriculum_item where version = '2017' and code = 'CTEPC-2.1.1'), 'secondaire', array['S3', 'S4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Appliquer : Identifier et expliciter les présupposés et les enjeux dans la formulation d’une question ; être capable de reformuler la question d’une autre manière', 'Compétences terminales de l''éducation à la philosophie et à la citoyenneté (humanités générales, technologiques, professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Edu-Philo-Citoyen.pdf)', '2017') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
