insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTES-PHY4-A5', (select id from public.curriculum_item where version = '2014' and code = 'CTES-PHY4'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Appliquer : Mener une recherche expérimentale pour identifier et quantifier les paramètres qui font varier l''accélération d''un mobile (loi fondamentale de la dynamique)', 'Compétences terminales et savoirs requis en éducation scientifique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Edu-Scientifi.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTES-PHY4-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTES-PHY4'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : Justifier une affirmation de la sécurité routière du type: « une collision d’une voiture à 90 km/h contre un mur correspond à la chute de cette même voiture d’une hauteur de 11 étages »', 'Compétences terminales et savoirs requis en éducation scientifique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Edu-Scientifi.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
