insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTETT', null, 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation manuelle et technique', 'domaine', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques)', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Tech-Tech.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTETT-1', (select id from public.curriculum_item where version = '2004' and code = 'CTETT'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation manuelle et technique', 'competence', '2.1.1. Produire personnellement un document écrit en langue française, présenté avec un traitement de texte, d''une manière structurée, compréhensible et lisible pour un lecteur non initié dans le but de l''éclairer sur une question, un problème ou une thématique', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Tech-Tech.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTETT-2', (select id from public.curriculum_item where version = '2004' and code = 'CTETT'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation manuelle et technique', 'competence', '2.1.2 Communiquer oralement en langue française avec une personne et/ou un groupe de personnes en utilisant, si nécessaire, divers supports dans le but d''informer sur une question, un problème ou une thématique', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Tech-Tech.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTETT-3', (select id from public.curriculum_item where version = '2004' and code = 'CTETT'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation manuelle et technique', 'competence', '2.1.3. A partir d''un ensemble d''observations qui pourront être confrontées à des sources théoriques parfois divergentes et en s''appuyant si nécessaire sur des outils scientifiques et mathématiques (validité et adéquation) établir, personnellement ou en groupe, un plan de recherche et décrire les modalités de traitement des informations afin de résoudre une situation problème significative pour l''élève', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Tech-Tech.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTETT-4', (select id from public.curriculum_item where version = '2004' and code = 'CTETT'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation manuelle et technique', 'competence', '2.1.4. Formuler des questions ou des hypothèses, par écrit ou oralement, dans un langage précis et adéquat à l''adresse d''une personne ressource dans le but de se forger une opinion et d''émettre un avis nuancé, en son propre nom et/ou au nom d''un groupe, sur des sujets en rapport avec son environnement', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Tech-Tech.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTETT-5', (select id from public.curriculum_item where version = '2004' and code = 'CTETT'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation manuelle et technique', 'competence', '2.2.1. Effectuer personnellement ou en groupe l''analyse et la modélisation d''un système en réponse à une situation problème', 'Compétences terminales et savoirs requis en éducation technique et technologique (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Tech-Tech.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
