insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R3', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Les continents, les océans, les hémisphères Nord et Sud, l’équateur, les tropiques, les cercles polaires, le méridien de Greenwich.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R4', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Population Les espaces peuplés : Asie de l’Est (Chine), Asie du Sud (Inde, Pakistan), Indonésie, Golfe de Guinée (Nigéria), Région des Grands Lacs africains, Est de l’Amérique du Nord, Europe. Les espaces vides : Amazonie, cuvette du Congo, Bornéo, Sahara, centre de l’Australie, péninsule arabique, Gobi, Nord du 60e parallèle Nord, Antarctique, Himalaya, Rocheuses, Andes. Les 15 aires urbaines les plus peuplées du Monde.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R5', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Bioclimat Pour les espaces peuplés et vides, les principales caractéristiques des climats associés aux paysages naturels : forêt tropicale humide, savane, désert, forêt tempérée, forêt boréale, steppe et toundra.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R6', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Orohydrographie Principaux reliefs : Himalaya, Rocheuses, Andes, Rift africain. Principaux fleuves : Amazone, Mississippi, Gange, Niger, Huang He, Yangzi Jiang, Congo, Nil, Mékong, Indus, Brahmapoutre.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
