insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R9', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Bioclimat Paysages naturels clés et climats associés : garrigue/maquis, forêt de feuillus, taïga, toundra. Régions européennes: bassin méditerranéen, Europe tempérée, Europe continentale, Europe septentrionale.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R10', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Orohydrographie Principaux reliefs : Alpes, Pyrénées, plaines de l’Ouest et du Nord, Oural. Principaux cours d’eau européens : Rhin, Rhône, Danube. Principaux cours d’eau belges : Meuse, Escaut, Yser, Sambre. Océans/Mers : Mer du Nord et Manche, Mer Méditerranée, Mer Noire, Mer Baltique.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTGEO-D3-TECHNO-R11', (select id from public.curriculum_item where version = '2018' and code = 'CTGEO-D3-TECHNO'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Ressource : Tectonique des plaques : séismes, épicentre, magnitude, volcans, éruption effusive, explosive, nuées ardentes, coulées de lave, tsunami.', 'Compétences terminales et savoirs communs en géographie (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/CT_HGT_Geographie.pdf)', '2018') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
