insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST2-2-A1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST2-2'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Au départ d’un témoignage ou d’un point de vue inédit, mais d’un genre familier, relatif à une situation vue en classe, répondre à quelques questions clés qui permettent de l’apprécier de manière critique.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST2-2-A2', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST2-2'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Au départ de réponses à ces questions clés à propos d’un témoignage ou d’un point de vue inédit, mais d’un genre familier, relatif à une situation vue en classe, formuler une raison de se fier et/ou de se méfier.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST2-2-A3', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST2-2'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Identifier dans un document inédit, mais d’un genre familier, relatif à une situation vue en classe, une caractéristique du concept abordé.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST2-2-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST2-2'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Transférer : Apprécier de manière critique un témoignage ou un point de vue inédit, mais d’un genre familier relatif à une situation vue en classe en énonçant une ou plusieurs raisons de s’y fier et/ou de s’en méfier.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST2-2-K1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST2-2'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Connaître : Énoncer quelques questions clés à se poser pour apprécier de manière critique un témoignage ou un point de vue d’hier ou d’aujourd’hui.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
