insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-1-A2', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-1'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Compléter un support au choix (tableau, schéma, représentation du temps) en replaçant dans son contexte temporel une information puisée dans un document inédit relative à une situation non vue et à une ou des caractéristiques du concept abordé.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
