insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-C1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Compétence : CRITIQUER', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-A1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Au départ d’un ensemble limité de témoignages ou de points de vue inédits, mais d’un genre familier, relatif à une situation vue en classe, répondre à quelques questions clés qui permettent de les apprécier de manière critique.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-A2', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Au départ des réponses à ces questions clés, formuler une ou plusieurs raisons de se fier et/ou de se méfier.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-A3', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Au départ de témoignages ou de points de vue inédits relatifs à une même situation, vue en classe, repérer des concordances, des divergences.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-A4', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : Identifier dans un ensemble limité de témoignages ou de points de vue, mais d’un genre familier, relatif à une situation vue en classe, une ou des caractéristiques du concept abordé.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Transférer : Apprécier de manière critique un ensemble de témoignages ou de points de vue inédits, mais d’un genre familier relatif à une situation non vue en classe, en énonçant une ou plusieurs raisons de s’y fier et/ou de s’en méfier et en repérant des concordances, des divergences en lien avec le concept abordé.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-K1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Connaître : Énoncer quelques questions clés à se poser pour apprécier de manière critique un témoignage ou un point de vue d’hier ou d’aujourd’hui.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-K2', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Connaître : À partir d’exemples vus en classe, expliciter en quoi les réponses à ces questions invitent tantôt à se fier, tantôt à se méfier d’un témoignage ou d’un point de vue d’hier ou d’aujourd’hui.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-HIST3-2-K3', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-HIST3-2'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Connaître : Énoncer des caractéristiques du concept abordé et les expliciter à partir d’un exemple vu en classe.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
