insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO2-3-A2', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO2-3'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : À partir d’un portefeuille donné de représentations cartographiques familières et diversifiées, représenter sur une carte, à l’aide de figurés cartographiques, les zones de faible ou de forte valeur pour décrire des disparités spatiales en lien avec le thème étudié.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO2-3-A3', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO2-3'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : À partir d’un portefeuille donné de représentations cartographiques familières, diversifiées et utilisant le même type de figuré que celui utilisé pour l’objet traité, sélectionner des représentations cartographiques qui sont en lien avec une disparité spatiale observée.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO2-3-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO2-3'), 'secondaire', array['S3', 'S4']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Transférer : À partir de documents variés concernant une situation nouvelle en lien avec les thèmes, sur base d’un fond de carte donné, compléter une représentation cartographique pour décrire la répartition spatiale d’objets dans l’espace.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
