insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO3-1-A1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO3-1'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : À partir de documents variés, décrire la répartition spatiale des objets étudiés pour mettre en évidence des disparités spatiales, en utilisant les repères et le vocabulaire adéquats, sous différentes formes', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO3-1-A2', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO3-1'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : À partir de documents variés, décrire la répartition spatiale des objets étudiés à au moins deux moments pour situer leur dynamique, en utilisant les repères et le vocabulaire adéquats sous différentes formes', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO3-1-A3', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO3-1'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Appliquer : À partir de documents variés, comparer ces disparités spatiales ou ces dynamiques spatiales en les plaçant dans un cadre spatial plus large pour relativiser leur importance, en utilisant les repères et le vocabulaire adéquats.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTHGQ-GEO3-1-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTHGQ-GEO3-1'), 'secondaire', array['S5', 'S6', 'S7']::text[], array['technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Transférer : Sur base d’un dossier documentaire nouveau et pour un espace donné, décrire, sous une forme au choix, la répartition et/ou la dynamique spatiale d’objets liés à un thème pour mettre en évidence des disparités spatiales, en utilisant les repères et le vocabulaire adéquats.', 'Compétences terminales et savoirs communs en formation historique et géographique (humanités professionnelles et techniques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_et_7e_PROF_et_techni_de_qualif/2014_CT_HPT_Form-Hist-Geo.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
