insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO5-T2', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO5'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : A partir de documents relatifs à une application biotechnologique (par exemple : production d’insuline, d’hormone de croissance, OGM,…), décrire l’impact de cette application sur notre quotidien ou sur l’environnement.', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO5-T3', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO5'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : A partir de la lecture de différents documents, participer à un débat contradictoire argumenté scientifiquement (ou faire réaliser par les élèves un argumentaire scientifique), sur les avantages et les inconvénients liés à l’utilisation des OGM.', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
