insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-C1', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Compétence : Identifier et expliquer l’impact significatif d’activités humaines sur un écosystème.', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-C2', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Compétence : Développer une argumentation scientifique pour critiquer une action de l’être humain sur un écosystème, puis proposer des solutions préventives et curatives.', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-A1', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Appliquer : Par l’observation d’écosystèmes, montrer la nécessité de les préserver en mettant en évidence les services qu’ils rendent.', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-A2', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Appliquer : Expliquer que certaines activités humaines peuvent modifier le fonctionnement d’un écosystème :(par exemple : le déversement de lisier, l’introduction d’une espèce invasive, la surpêche,…).', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-A3', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Appliquer : Calculer son empreinte écologique (en fonction de son alimentation, de ses déplacements, de sa consommation, …).', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : Participer à un débat scientifiquement argumenté pour proposer, en tant que citoyen responsable, des pistes de solutions, afin de protéger les écosystèmes (par exemple : changement des habitudes de consommation, lutte contre la surconsommation d’eau douce, choix énergétique, valorisation des déchets,…).', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-T2', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : Expliquer comment certaines activités humaines favorisent le développement, le maintien ou la restauration de la biodiversité (par exemple : maillages vert et bleu, transhumance du mouton sur les pelouses calcaires, protection de sites et d’espèces (hotspots et projets « life »), sylviculture diversifiée, …).', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSB-BIO6-K1', (select id from public.curriculum_item where version = '2014' and code = 'CTSB-BIO6'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : A partir de documents, identifier quelques causes pouvant être à l’origine d’une diminution de la biodiversité dans un écosystème.', 'Compétences terminales et savoirs requis en sciences de base (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-base.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
