insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-C4', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Compétence : Distinguer un modèle (issu de faits scientifiques) d’une croyance pour expliquer l’apparition de la vie, l’évolution de la vie sur Terre et de la biodiversité.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
