insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K3', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Développé de l’hypertexte Transférer', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K4', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Mettre en œuvre une démarche d’investigation pour découvrir l’implication de quelques gènes et l’influence de l’environnement lors du développement de certaines maladies.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K5', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : A partir de la lecture de différents documents, participer à un débat contradictoire argumenté scientifiquement (ou faire réaliser par les élèves un argumentaire scientifique) sur le développement des biotechnologies (avantages, inconvénients et problèmes éthiques liés par exemple à l’utilisation des OGM, au diagnostic prénatal des maladies héréditaires, à la thérapie génique chez l’Homme …).', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K6', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : A partir de l’analyse de documents décrivant un cas concret d’apparition d’une nouvelle espèce (par exemple : les pinsons de Darwin, les moustiques du métro de Londres, les souris de Madère, le lézard des ruines,…), mettre en évidence les mécanismes particuliers qui permettent d’expliquer l’apparition de ces nouvelles espèces.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K7', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Expliquer à l’aide d’un arbre phylogénétique (par exemple : celui des vertébrés) que la classification scientifique actuelle des êtres vivants se fonde sur la théorie de l’évolution.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K8', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : A la lumière de la théorie néodarwinienne, critiquer les arguments développés dans des théories (par exemple : le fixisme, le créationnisme, le lamarckisme,…). qui tentent d’expliquer l’origine et l’évolution de la vie à la surface de la Terre.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO8-K9', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO8'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Développé de l’hypertexte Connaître', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
