insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO9-A4', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO9'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Appliquer : Calculer son empreinte écologique (en fonction de son alimentation, de ses déplacements, de sa consommation, …).', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO9-T1', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO9'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : Participer à un débat scientifiquement argumenté pour proposer, en tant que citoyen responsable, des pistes de solutions, afin de protéger les écosystèmes (par exemple : changement des habitudes de consommation, lutte contre la surconsommation d’eau douce, choix énergétique, valorisation des déchets,…).', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO9-T2', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO9'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Transférer : Expliquer comment certaines activités humaines favorisent le développement, le maintien ou la restauration de la biodiversité (par exemple : maillages vert et bleu, transhumance du mouton sur les pelouses calcaires, protection de sites et d’espèces (hotspots et projets « life »), sylviculture diversifiée …).', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO9-K1', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO9'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : A partir de documents, identifier quelques causes pouvant être à l’origine d’une diminution de la biodiversité dans un écosystème.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO9-K2', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO9'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Décrire à partir d’un exemple (tétras-lyre, cigognes noires,…), les caractéristiques biologiques qui font qu’une espèce est menacée.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-BIO9-K3', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-BIO9'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Décrire à partir d’un exemple (balsamine de l’Himalaya, berce du Caucase, coccinelle asiatique, Caulerpa taxifolia, …), les caractéristiques biologiques d’une espèce invasive.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
