insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTSG-PHY7-K3', (select id from public.curriculum_item where version = '2014' and code = 'CTSG-PHY7'), 'secondaire', array['S5', 'S6']::text[], array['general', 'technique', 'specialise']::text[], 'Sciences', 'attendu', 'Connaître : Classer les ondes sonores et lumineuses comme transversales ou longitudinales ; mécaniques ou électromagnétiques et selon le milieu de propagation.', 'Compétences terminales et savoirs requis en sciences générales (humanités générales et technologiques) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/FORM_COM_2et3_degres_TRANSITION/2014_CT_HGT_Sciences-gen.pdf)', '2014') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
