insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-19', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'competence', 'Compétences transversales – Utiliser les concepts, les modèles, les procédures et les instruments qui s''imposent pour une tâche technique donnée en les maîtrisant, en comprenant leur emploi, en étant conscient de leurs possibilités et de leurs limitations ainsi que des consignes de sécurité', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
