insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-1', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Analyser et résoudre les applications et problèmes liés aux lois fondamentales.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-2', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Analyser les schémas fonctionnels, structurels d''un système ou d''un objet technique.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-3', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Retenir, parmi l''ensemble des compétences instrumentales mises en œuvre, celles qui visent la maîtrise de l''usage des instruments de contrôle et de mesure, de la mise en œuvre des équipements et de l''utilisation des outils de représentation (tableaux et planning).', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-4', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Choisir une méthode et un appareillage permettant de contrôler les caractéristiques techniques des matériaux, d''un élément d''un système, d''un système.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-5', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Décrire à partir des spécifications du cahier des charges, le comportement d''une fonction principale ou d''un ensemble de fonctions, vérifier par simulation et/ou par des essais et des mesures, la conformité de ses caractéristiques fonctionnelles.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-6', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Analyser les solutions technologiques existantes, en référence aux spécifications du cahier des charges.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-7', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Produire des supports techniques cohérents relatifs à une étude, à un projet, à un ou à des systèmes techniques et les communiquer en respectant la terminologie, les normes et les défendre.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('CTTEC-1-8', (select id from public.curriculum_item where version = '2004' and code = 'CTTEC-1'), 'secondaire', array['S3', 'S4', 'S5', 'S6']::text[], array['technique']::text[], 'Formation manuelle et technique', 'attendu', 'Interpréter et modéliser des systèmes techniques intégrant des sous-systèmes conformément aux exigences d''un cahier des charges. L''utilisation d''un vocabulaire précis, l''analyse des schémas, des représentations graphiques, des modèles permettent de diriger l''analyse, d''organiser l''espace et le temps, ou d''orienter les choix d''action.', 'Compétences terminales et savoirs requis en technologie (options de base groupées, technique de transition) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/secondaire_ordinaire/Organisation/Contenus_apprentissages_Secondaire/competences_terminales/HUM_GEN_et_TECH_2et3_degres/2004_CT_HGT_Edu-Technolo.pdf)', '2004') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
