insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-25-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C25'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec SF2 et SF4, par ex : - « Stripsody », C. Berberian. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-25-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C25'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', '▶ Expression : Notamment en lien avec C2, par ex : - Chansons pour rythmer la journée (par ex : « Pour se mettre en rang », Gibus). - Chansons et percussions corporelles (par ex : « Main, pied, cuisse », Ici Baba). - « Chansons à gestes », J. René. - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-25-4', (select id from public.curriculum_item where version = '2022' and code = 'EA-C25'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - Les plasticiens* de la forme (par ex : P. Picasso, H. Matisse, A. Calder, l’art africain premier, J. Dubuffet…). - L’ornementation (par ex : l’art égyptien, l’art de l’Asie antérieure, la sculpture romane…). - L’imaginaire (par ex : F. Kahlo, S. Dali, R. Magritte, J. Mirõ, M. Chagall, J. Bosch...).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites et observations de préférence in situ, identifier : - un lieu culturel de son environnement et/ou un spectacle (théâtre, concert, cinéma, chapiteau…) ; - des éléments du patrimoine* local ; - des objets de diverses cultures.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-7-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Identifier le rythme* des mouvements : leur vitesse, leur durée (lent/ brusque/rapide/arrêt/accélération).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-7-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Identifier et définir la pulsation*.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-7-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Identifier des rythmes* formels (par ex : frise, juxtaposition, répétition…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-8-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Identifier : - les actions motrices (par ex : tourner, tirer, pousser...) ; - les types de mouvements (long/court/ample/arrondi/linéaire/ discontinu/saccadé...).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
