insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-P2-8-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Connaitre des notions de techniques vocales (respiration, pose de la voix, échauffement…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
