insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-S3-64-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C64'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', '- Théâtre contemporain lié à l’actualité culturelle. - Danse contemporaine (par ex : M.A. De Mey, A.T. de', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-S3-65-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C65'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Keersmaeker, M.-C. Pietragalla, M. Béjart…). Expression musicale ▶ Écoute : Notamment en lien avec S2 et SF2, par ex : - « Chœur des esclaves » de « Nabucco », G. Verdi. - « Ode à la joie », 9e Symphonie, L. Beethoven. - « Sicilienne » Op. 68, R. Schumann. - « Sicilienne », J.S. Bach, BWV 1031. - « Breakaway », K. Clarkson. - « We Are the Champions », Queen. - « We Will Rock You », Queen. - « Jailhouse Rock », E. Presley. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-S3-65-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C65'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', '▶ Expression : Notamment en lien avec S2 et C2, par ex : - « Le Jazz et la Java », C. Nougaro. - « Le Plat Pays », J. Brel. - « La foule », E. Piaf. - « Hallelujah », L. Cohen. - « L’amour est un oiseau rebelle » de « Carmen », G. Bizet. - « Carmen », Stromae. - « Hymne européen ». - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EA-S3-65-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C65'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - La vidéo et l’art numérique (par ex : B. Viola, P. Sorin, N. McLaren…). - Les photographes témoins (par ex : C. Sherman, A. Sander, D. Lange, S. Salgado…). - L’architecture (par ex : les châteaux, la Renaissance, l’art roman, l’art nouveau, le Bauhaus, Le Corbusier, C. Perriand, Z. Hadid, F. Gehry, J. Nouvel…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
