insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-54-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C54'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Analyser les influences positives et négatives du numérique sur sa pratique physique.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-212-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C212'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Se connaitre et s’ouvrir aux autres requièrent de développer une conscience de soi et de l’autre, du temps et de l’espace ainsi que du collectif.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-213-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C213'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Exemples de contenus ou d’attendus contributifs GSS4 Construire une image positive de soi, développer son sentiment de compétence et plus largement son estime de soi à adopter un mode de vie sain et actif, dans et en dehors de l’école : Identifier ses forces en activité physique. (C, P3-P4) Énoncer ses forces en activité physique. (C, P5) HSC1 Respecter des règles convenues dans l’intérêt du groupe et de chacun en fonction du but à atteindre : Assumer différents rôles et responsabilités. (SF, P1 à P6) Assumer tous les rôles. (SF, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-214-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C214'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'HSC3 Interagir positivement avec ses partenaires. S’affirmer en respectant les autres (assertivité, vigilance aux stéréotypes…) : Respecter les autres et le milieu. (SF, P1-P2) Adopter un comportement fair-play. (C, P1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-215-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C215'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'GSS3 Identifier ses émotions, mobiliser des techniques de gestion des émotions et du stress : Verbaliser l’effet croisé de ses émotions et de celles des autres sur la dynamique du groupe. (SF, P5 à S3) Mobiliser les techniques expérimentées pour gérer ses émotions et ses stress. (SF, S1 à S3) GSS4 Construire une image positive de soi, développer son sentiment de compétence et plus largement son estime de soi à adopter un mode de vie sain et actif, dans et en dehors de l’école : Admettre les différences en évitant les stéréotypes de genre, morphologiques, de capacités, médicaux, comportementaux, intellectuels… en rapport à l’engagement dans l’activité. (SF, P5-P6) HSC1 Respecter des règles convenues dans l’intérêt du groupe et de chacun en fonction du but à atteindre : Se comporter en respectant des règles. (C, P1 à S3) Participer à l’élaboration et au respect de règles communes. (SF, P3 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-216-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C216'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'GSS1 Adopter un style de vie sain et actif, être activement responsable de sa condition physique : Identifier les possibilités d’activités physiques durant la journée. (C, P1-P2) Planifier ses activités hebdomadaires pour atteindre les recommandations de santé. (C, P6) Mettre en pratique et ajuster son planning personnel d’activités physiques. (C, S1-S2) Mettre en pratique les principes de la condition physique de façon à mener une vie saine et active. (C, S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-217-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C217'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'HSC2 Contribuer activement à la construction d’une réalisation commune : Décider et agir dans une action commune pour se mettre au service de l’action collective. (C, P5 à S2)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-217-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C217'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Apprendre à apprendre requiert que les élèves développent les opérations mentales de base susceptibles de les aider à organiser leurs apprentissages et la ré-', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-218-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C218'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maitriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-219-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C219'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'GSS1 Adopter un style de vie sain et actif, être activement responsable de sa condition physique : Reconnaitre ses capacités et continuer à s’engager dans les activités physiques proposées', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-220-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C220'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'avec l’objectif de maintenir et d’améliorer sa condition physique et son bien-être. (C, S1 à S3) Mettre en pratique et ajuster son planning personnel d’activités physiques. (C, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-220-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C220'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'GSS4 Construire une image positive de soi, développer son sentiment de compétence et plus largement son estime de soi à adopter un mode de vie sain et actif, dans et en dehors de l’école : Identifier dans l’année ses propres réussites, même partielles, à adopter un mode de vie sain et actif. (SF, P5-P6) Réaliser une trace de ses réussites à adopter un mode de vie sain et actif. (SF, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-221-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C221'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('EP-S3-222-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C222'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'GSS5 Exercer sa pensée critique sur divers sujets liés à la santé et au bien-être : S’interroger et formuler des questions sur divers sujets liés à la santé. (C, P1 à S3) Exprimer une opinion argumentée sur un sujet lié à la santé et au bien-être. (C, S3) Repérer des images stéréotypées du corps véhiculées par la société (médias, réseaux sociaux…). (SF, P5 à S3) Identifier des effets négatifs sur la santé de la sédentarité et des excès liés à certaines', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
