insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P3-75-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C75'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', '- en tenant compte de l’intention et du destinataire ; - en adaptant le volume, le débit, la posture, les expressions et le regard ; - en utilisant les étapes d’une prise de parole préparée : se présenter, introduire le sujet, le présenter, conclure. - en tenant compte de l’intention et du destinataire ; - en adaptant le volume, le débit, la posture, les expressions et le regard ; - en utilisant des règles de courtoisie.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
