insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P4-16-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C16'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Connaitre les constantes orthographiques liées à l’emploi : - de certains graphèmes (en lien avec une famille morphologique*) ; - de certains phonèmes (le son /ɛj/ s’écrit -eil d’un mot masculin, -eille d’un mot féminin et -eill à l’intérieur du mot…) ; - de certains accents (a/à, ou/où…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
