insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P4-144-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C144'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', '- en restant dans le sujet ; - en tenant compte de l’intention, du destinataire (diversité, réactions des interlocuteurs), des freins et des facilitateurs de la communication ; - en l’organisant selon une structure textuelle adéquate ; - en utilisant des connecteurs* logiques et chronologiques, spatiaux, de cause/explication, d’addition ; - en utilisant les substituts lexicaux ; - en utilisant le lexique courant ou spécifique à une thématique ou un champ disciplinaire adéquat ; - en utilisant les formes verbales qui assurent la cohérence temporelle* et en utilisant les structures de phrase correctes ; - en assurant la reprise d’information (substituts lexicaux et pronoms personnels).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
