insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-84-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-C84'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Connaitre la conjugaison des verbes : - en -ER avec variation du radical ; - en -IR (tous) ; - en -(D)RE qui forment un participé présent en -dant ; - irréguliers : « prendre », « mettre », « tenir », « venir » et leurs dérivés « faire », « dire », « devoir », « partir », « pouvoir », « savoir », « voir », « vouloir » et les verbes comme « ouvrir ».', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
