insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-18-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C18'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Connaitre des démarches pour s’adapter au contexte d’écoute : - conduites sociales adéquates (attente, silence, gestes, sons) ; - écoute attentive ; - comportement non verbal approprié selon la modalité retenue (audio/vidéo, public/privé…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
