insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-65-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C65'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'En répondant à des questions ou en produisant un dessin, des phrases ou une action qui donne à voir certains des éléments suivants :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-94-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C94'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - les connaissances personnelles mobilisées ; - l’intention de l’auteur ; - les caractéristiques du message entendu pour en identifier le genre ; - les relations entre les éléments (texte-illustrations éventuelles, liens logiques, chronologiques, organisateurs textuels, reprise de l’information*) ; - les informations essentielles, le sens global du message ; - le sens du message grâce à la prise en compte des indices grammaticaux, verbaux et du fonctionnement de la langue.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-64-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C64'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Attendus ÉCOUTER', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-153-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C153'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - l’intention de l’auteur ; - les caractéristiques du message entendu pour en identifier le genre ; - les relations entre les éléments (chronologie, texte-illustrations éventuelles, organisateurs textuels, reprise de l’information*) ; - le sens du message grâce à la prise en compte des indices grammaticaux, verbaux et du fonctionnement de la langue ; - les éléments réels/imaginaires, vraisemblables/invraisemblables ; - les liens entre les actions et les motivations des personnages ; - une émotion ressentie, l’empathie éprouvée pour un personnage (traits de caractère, valeurs, comportements) ; - les informations essentielles, le sens global du message ; - les procédés langagiers et artistiques utilisés par les autrices et auteurs pour construire le ou les sens de l’œuvre.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-154-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C154'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'En imaginant une suite cohérente à un récit. - les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - l’intention de l’auteur ; - les caractéristiques du message entendu pour en identifier le genre ; - les relations entre les éléments (liens logiques, organisateurs textuels, reprise de l’information*) ; - les informations essentielles, le sens global du message ; - le sens du message grâce à la prise en compte des indices grammaticaux, verbaux et du fonctionnement de la langue. - les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - l’intention de l’auteur ; - les caractéristiques du message entendu pour en identifier le genre ; - les relations entre les éléments (chronologie, liens logiques, organisateurs textuels, reprise de l’information*) ; - les informations essentielles, le sens global du message ; - le sens du message grâce à la prise en compte des indices grammaticaux, verbaux et du fonctionnement de la langue.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
