insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-74-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C74'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Rédiger un écrit qui combine plusieurs des éléments ci-dessous en mobilisant des ressources (référentiels) :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P5-75-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C75'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', '- en restant dans le sujet ; - en tenant compte de l’intention et du destinataire ; - en l’organisant selon une structure textuelle simple donnée ; - en utilisant les traits de ponctuation adéquats ; - en orthographiant correctement les mots connus et inconnus et en appliquant les règles d’orthographes grammaticale et lexicale ; - en utilisant les connecteurs* ; - en utilisant les modes et les temps appropriés pour assurer la cohérence temporelle* ; - en utilisant les substituts lexicaux et grammaticaux ; - en recourant aux lexiques courant et spécifique à une thématique ou un champ disciplinaire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
