insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-P6-16-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C16'), 'primaire', array['P6']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Connaitre les préfixes et leur impact sur le sens des mots : - in- (im-, il-, ir-) : donne un sens de négation (« immortel », « irréel ») ou donne le sens «dans» au mot (« intérieur ») ; - en- : donne le sens «dans» au mot (« enterrer ») ; - re- (ré-, r-) : donne le sens «à nouveau» (« revenir ») ; - de- (dés) : donne un sens de séparation (« décolorer », « désespoir »).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
