insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-S2-183-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C183'), 'primaire', array['S2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Identifier les effets de sens produits par le travail de l’auteur : - gestion de la temporalité (linéarité, anticipation, retours en arrière…) ; - récits parallèles, enchâssés ; - rythme de la narration (ellipse, résumé…), du montage ; - focalisation interne/externe ; - narration unique/polyphonique ; - présence d’inventions langagières (figures de style…) ; - ton utilisé (sérieux, comique, ironique…) ; - mise en page ; - représentation figurative ou non figurative (choix de couleurs, floutage, cadrage, incrustation…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
