insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('FR-S3-178-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-C178'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Français', 'attendu', 'Identifier : - les unités de sens (phrases, paragraphes) ; - la phrase verbale/non verbale ; - les types et formes de phrases (en fonction des productions demandées) ; - les expansions du nom (épithète, complément du nom, apposition).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
