insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P4-5-5', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Compléter une frise chronologique graduée en siècles du Ier siècle av. J.-C. à aujourd’hui par des traces ou des informations relatives à la thématique de l’année et l’annoter en mobilisant des repères temporels significatifs.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P4-5-6', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Sélectionner, parmi quatre ou cinq documents, une trace du passé et un travail postérieur, en lien avec un moment clé de l’évolution de l’accès aux savoirs et à l’instruction.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P4-5-7', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Sur la base de deux documents traitant de l’accès aux savoirs et à l’instruction, construire un tableau à simple entrée pour comparer une réalité de vie de l’élève avec celle vécue par un autre, durant un des moments clés étudiés et identifier des éléments qui changent et des éléments qui ne changent pas, en mobilisant des repères temporels significatifs et un vocabulaire temporel spécifique.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P5-1-1', (select id from public.curriculum_item where version = '2022' and code = 'HG-C1'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Nommer et ordonner les périodes conventionnelles.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P5-1-2', (select id from public.curriculum_item where version = '2022' and code = 'HG-C1'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Nommer et situer par rapport aux moments clés les cinq moments de rupture qui ont marqué l’évolution des modes de production et de consommation dans nos régions.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
