insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-S1-5-6', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['S1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Compléter une frise chronologique du IVe millénaire av. J.-C. à nos jours par des traces ou des informations relatives à la thématique de l’année, le début de l’ère chrétienne et les périodes conventionnelles et construire le plan d’un court texte explicatif, en mobilisant des repères temporels significatifs et des termes pour caractériser ces repères.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
