insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-S1-5-8', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['S1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Sur la base de documents traitant de l’histoire du fait religieux, construire un tableau à double entrée pour inscrire une réalité d’aujourd’hui dans une perspective historique et l’annoter en expliquant des continuités, des changements, en mobilisant des repères temporels significatifs et un vocabulaire temporel spécifique.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
