insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-6', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Exemplifier le fait d’être à la fois un individu singulier (par exemple, au niveau physique et du caractère) et membre de différents groupes (groupe-classe, membre d’une famille, etc.).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-7', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Nommer différentes personnes intervenant dans le cadre scolaire, identifier leur rôle (ex. : directrice/directeur, instituteur/institutrice, élève, accueillante/accueillant, personnel ouvrier…) et certaines de leurs activités (ex. : organiser, enseigner, apprendre, surveiller, entretenir…).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-8', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Exemplifier différentes manières de communiquer avec ses camarades de classe, avec son instituteur/institutrice, avec la direction… Exemplifier des règles qui varient selon différentes situations dans le cadre scolaire (ex. : en classe, au réfectoire, dans les rangs, dans la cour de récréation).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-9', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Sur la base d’exemples concrets et tirés du quotidien, identifier des biens individuels et collectifs.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-10', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Identifier l’existence de règles différentes dans l’utilisation du langage selon les contextes, en observant différentes manières de communiquer (ex. : langage familier entre copains, dans la cour de récréation, en classe, avec les adultes…).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-11', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Associer une combinaison de pièces (1 €, 2 €) et/ou billets (5 €, 10 €, 20 €) avec le prix (inférieur ou égal à 20 €) d’un bien.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-12', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Formuler ensemble (élèves et enseignant) des raisons qui expliquent des différences de règles de conduite entre l’utilisation d’un bien collectif et d’un bien individuel.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-13', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Expliciter en quoi un même besoin peut être satisfait de différentes manières.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('HG-P1-13-14', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Expliciter pourquoi un même comportement peut être accepté ou pas dans des situations différentes (ex. : cour de récréation/classe, cours d’éducation physique/ autre cours, en discutant avec un copain/la direction de l’école…).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
