insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-C341', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'competence', 'B. Exécuter • s’appuyer sur des acquis et expériences antérieurs • prendre le risque de s’exprimer avec les ressources linguistiques disponibles • le cas échéant, maintenir le contact visuel avec le destinataire du message • trouver les moyens de contourner les difficultés, en mobilisant les ressources verbales (mots internationalement partagés, synonymes,', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
