insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-C352', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'competence', 'connecteurs simples et n’impliquant pas de modification syntaxique', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-C353', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'competence', 'Dynamique • l’élève participe aux échanges et peut les animer ponctuellement • l’élève échange sans restituer intégralement un contenu appris par cœur • l’élève peut attirer l’attention de l’interlocuteur pour initier, relancer la conversation • l’interlocuteur, natif ou assimilé - s’adresse - se montre - s’exprime dans une Lexique • usage correct d’un répertoire - de mots - de mots internationalement partagés - d’expressions, en lien avec la sphère précitée', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-C354', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'competence', 'Grammaire • usage correct de structures simples • utilisation adéquate de conjonctions et/ou d’organisateurs textuels n’impliquant pas de modification syntaxique • étendue grammaticale : outre les items pour lesquels des attendus grammaticaux ont été formulés spécifiquement cette année, les productions des élèves pourraient faire appel à des notions grammaticales qui seront abordées ultérieurement, sans qu’une erreur éventuelle relative à cette notion ne pénalise l’élève Prononciation, intonation et débit • globalement compréhensible, malgré un accent non natif marqué et malgré des erreurs qui peuvent parfois nuire à la communication • intonation adéquate, au service de l’intention communicative • débit relativement fluide, en dépit de pauses et d’hésitations Correction sociolinguistique • utilisation correcte de marqueurs de relations sociales et de règles de politesse courants dans un registre de langue adapté à la situation', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
