insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-P4-12-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C12'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • prend la forme : - de réponses adéquates à des questions ; - de formules de politesse et de salutations. • respecte les caractéristiques reprises dans l’annexe 3 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
