insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-P4-14-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C14'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'attendu', 'Action en exécution d’une consigne au travers, par exemple d’un mouvement, d’une manipulation d’objet, d’un geste, d’un déplacement qui témoigne de la compréhension de l’injonction.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
