insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-S3-332-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C332'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'attendu', 'Lexique Lexique le message doit être constitué d’un répertoire usage correct d’un • de mots de base, de mots internationalement répertoire élémentaire partagés • de mots, de mots • d’expressions toutes faites, en lien avec la internationalement sphère précitée partagés • d’expressions simples, en lien avec la sphère précitée Grammaire Grammaire • support caractérisé par • utilisation de formes - des formes grammaticales simples et grammaticales - des structures syntaxiques mémorisées simples et de • étendue grammaticale des sujets : outre les structures items pour lesquels des attendus grammaticaux syntaxiques ont été formulés spécifiquement cette année, mémorisées les supports proposés aux élèves peuvent • étendue grammaticale déjà contenir notions grammaticales qui seront des sujets : outre abordées, à condition qu’elles ne portent pas les items pour préjudice à la compréhension lesquels des attendus grammaticaux ont été formulés spécifiquement cette année, les productions des élèves pourraient faire appel à des notions grammaticales qui seront abordées ultérieurement, sans qu’une erreur éventuelle relative à cette notion ne pénalise l’élève', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
