insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-S3-339-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C339'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'attendu', 'instructions (dessin animé, série, publicités ou électronique) émission, jeux, selfie) • invitation • mémo/liste • menu de restauration • affiche/poster À visée injonctive rapide • illustration commentée • consignes, • album jeunesse • schéma commenté instructions relatives • livre d’images (itinéraire, plan) à l’environnement • BD immédiat • calendrier À visée injonctive • annonce courte, par • blog • mémo/liste exemple, dans une • affiche/poster gare ou un magasin À visée injonctive • illustration commentée • tutoriel • liste • schéma commenté • consignes (itinéraire, plan) • recette simplifiée À visée informative/ injonctive • invitation pré-imprimée à compléter • mémo/liste • affiche/poster • illustration commentée • schéma commenté (itinéraire, plan) Exemples de stratégies à activer au besoin A. Cadrer A. Cadrer A. Planifier • sur la base des • sur la base des • se forger une éléments disponibles éléments visuels représentation avant l’écoute (titre, éventuels : mentale de la éléments visuels - identifier le type de production attendue éventuels) : document - anticiper le contenu - anticiper le contenu du message du message - anticiper les - anticiper les éléments lexicaux du éléments lexicaux du message message • envisager les informations à communiquer • prendre en compte le destinataire', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
