insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-S3-353-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C353'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'attendu', 'directement à l’élève, distinctement et simplement spontanément attentif et bienveillant (répétitions, reformulations, rectifications, non-verbal) langue standard sans accent régional marqué qui constituerait un obstacle à la compréhension Au niveau de la langue Lexique Lexique • le message doit être constitué • usage correct d’un - de vocabulaire très fréquent répertoire - d’expressions simples, en lien avec la sphère - de mots précitée - d’expressions, en lien avec la sphère précitée', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
