insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('LM-S3-354-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C354'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Langue moderne', 'attendu', 'Grammaire Grammaire • support caractérisé par des structures simples • usage • utilisation adéquate de conjonctions et/ou - de structures d’organisateurs textuels n’impliquant pas de simples modification syntaxique - de conjonctions et/ou • étendue grammaticale des sujets : outre les d’organisateurs items pour lesquels des attendus grammaticaux textuels n’impliquant ont été formulés spécifiquement cette année, pas de modification les supports proposés aux élèves peuvent syntaxique déjà contenir notions grammaticales qui seront • étendue grammaticale abordées, à condition qu’elles ne portent pas des sujets : outre préjudice à la compréhension les items pour lesquels des attendus grammaticaux ont été formulés spécifiquement cette année, les productions des élèves pourraient faire appel à des notions grammaticales qui seront abordées ultérieurement, sans qu’une erreur éventuelle relative à cette notion ne pénalise l’élève Prononciation, Orthographe intonation et débit • relative exactitude le locuteur, orthographique natif ou assimilé, des mots qui s’exprime appartiennent à • clairement et son répertoire écrit distinctement mémorisé • avec un débit lent • relative exactitude • avec un accent ne phonétique (mais nuisant pas à la pas forcément compréhension orthographique) des mots qui appartiennent à son vocabulaire oral Correction sociolinguistique Correction • l’élève comprend les marqueurs de relations sociolinguistique sociales et de règles de politesse courants dans • utilisation correcte un registre adapté à la situation de marqueurs de relations sociales et de règles de politesse courants dans un registre de langue adapté à la situation', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
