insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-3.2-20', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Utiliser la calculatrice pour vérifier le résultat d’une opération (addition, soustraction, multiplication).', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-3.2-21', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Utiliser les opérations réciproques (+, -) et (x, :) pour vérifier le résultat d’une opération.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-3.2-22', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Résoudre un problème faisant intervenir des opérations sur les nombres : -en traduisant une situation contextualisée par un dessin, une verbalisation puis l’écriture d’opérations mathématiques (+, -, x) ; - en effectuant les calculs ; - en communiquant le résultat avec précision ; - en vérifiant la plausibilité de la réponse, et verbaliser sa démarche.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-3.2-23', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Imaginer une situation en partant de la communication du résultat. Ex. : papa a payé 60 euros.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Utiliser les mots : - trier : « a ou n’a pas …» (selon le critère défini) ; Ex. : la couleur. - classer (selon des caractéristiques définies au sein d’un critère) ; Ex. : rouge, jaune, bleu…', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-2', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Reconnaitre une représentation de données en : - tableau ; - ensembles ; - arbre (dichotomique) ; - diagramme à bandes.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-3', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Collecter des informations à partir d’une question : - exigeant une réponse par oui ou par non ; - permettant un classement des données récoltées.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-4', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Organiser des objets représentés et des données : - par tri selon deux critères considérés successivement ; -par classement selon des caractéristiques déterminées au sein d’un critère.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-5', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Déterminer les critères appliqués dans l’organisation d’objets représentés.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-6', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Choisir, pour organiser des objets représentés : - un critère à appliquer à un tri ; - un critère et au moins deux caractéristiques à appliquer à un classement.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-7', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Compléter le support donné en fonction de la situation pour représenter un tri ou un classement : - deux ensembles incluant une intersection ; - un arbre dichotomique (deux critères) ; - un tableau à double entrée ; - un diagramme à bandes horizontales ou verticales.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-8', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Prélever des informations issues d’une représentation : - de deux ensembles incluant une intersection ; - d’un arbre dichotomique (deux critères) ; - d’un tableau à double entrée ; - d’un diagramme à bandes horizontales ou verticales.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P3-4.1-9', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Résoudre des problèmes de logique déductive en complétant un tableau à double entrée limité à seize cases.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P4-1.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-1.1'), 'primaire', array['P4']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Utiliser le vocabulaire exprimant des positions absolues : à côté de, contre, à l’intérieur, à l’extérieur, entre, sous, sur, dans, hors, autour de, face à face, dos à dos.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
