insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P5-1.2-33', (select id from public.curriculum_item where version = '2022' and code = 'MA-1.2'), 'primaire', array['P5']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Tracer dans un quadrillage, selon l’axe de symétrie donné, l’image d’un assemblage de figures. Tracer dans un quadrillage agrandi ou réduit, l’image d’une figure donnée.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
