insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-P6-2.2-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', 'Utiliser et symboliser : - les unités de longueur ; - les unités de capacité ; - les unités de masse ; - les unités d’aire y compris les mesures agraires : l’are (a), l’hectare (ha), le centiare (ca) ; - les unités de volume : le mètre cube (m³), le décimètre cube (dm³), le centimètre cube (cm³), le millimètre cube (mm³).', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
