insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MA-S1-3.1-22', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.1'), 'primaire', array['S1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Mathématiques', 'attendu', '- exprimer avec ses mots la relation entre le rang et le nombre d’éléments constituant le motif (ou la valeur du terme de la suite) ; - déterminer une valeur de la suite correspondant à un rang élevé ; - exprimer la relation entre le rang d’une figure et le nombre d’éléments constituant le motif (ou la valeur du terme de la suite), à l’aide des opérations mathématiques et du symbole « égal ».', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
