insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-302-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C302'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Sciences', 'attendu', 'Nommer, suite à des manipulations, l’état de l’eau liquide/ solide.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-303-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C303'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Sciences', 'attendu', 'Observer, lors de différentes expériences, que l’air se déplace (par exemple : lors de la pression d’une bouteille en plastique, l’air est passé dans le ballon de baudruche fixé au goulot).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
