insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M1-M2-339-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C339'), 'maternelle', array['M1', 'M2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Se situer en temps réel dans le temps et dans l’espace en : - utilisant le terme « maintenant » ; - nommant l’activité ; - nommant l’espace occupé dans la classe. (Par exemple : maintenant, je lis un livre dans l’espace lecture).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
