insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-344-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C344'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'S’approprier et utiliser adéquatement, en situation, des termes : - pour (se) situer dans une journée : avant, maintenant, pendant que, en même temps que, après ; - pour (se) situer dans le temps : maintenant, il y a longtemps ; - pour se situer dans sa famille proche (généalogie).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
