insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-364-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C364'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Présenter la famille ou les proches avec qui l’élève partage son quotidien.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-365-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C365'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Comparer au moins deux caractéristiques propres aux habitudes de vie (pour se déplacer, se vêtir, s’alimenter, se divertir…) des élèves de la classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-366-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C366'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'habitudes de vie : - d’aujourd’hui/d’autrefois ; - d’ici/d’ailleurs.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-367-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C367'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Se situer dans le temps et dans l’espace : - en utilisant les termes « avant », « maintenant », « après » ; - en nommant l’activité vécue/à vivre ; - en nommant le lieu où se déroule l’activité. (Par exemple : j’enfile mon manteau dans la classe avant d’aller jouer dans la cour de récréation).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-368-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C368'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation historique et géographique', 'attendu', 'Situer un fait/un événement dans le temps et dans l’espace : - en utilisant les termes « avant », « maintenant », « après » ; - en précisant le lieu. (Par exemple : après la récréation, nous irons voir un spectacle dans la salle de gymnastique).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M1-M2-369-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C369'), 'maternelle', array['M1', 'M2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Utiliser les formules de politesse et de savoir-vivre, en situation de vie : bonjour, au revoir, s’il vous plait, merci.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M1-M2-370-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C370'), 'maternelle', array['M1', 'M2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Utiliser adéquatement le nom des émotions ressenties.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M1-M2-371-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C371'), 'maternelle', array['M1', 'M2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Dire, avec ses mots, ce que je peux faire et ce que je ne peux pas faire, selon la situation.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
