insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-428-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C428'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', '- à la perception sensorimotrice : regarder, écouter, souffler, toucher ; - au schéma corporel : les parties du corps dont certaines articulations ; - à la motricité : marcher, courir, sauter, grimper, glisser, ramper ; - à la coordination motrice : tirer, pousser, lancer, rattraper, shooter, s’arrêter ; - à la notion d’équilibre : marcher en équilibre, se balancer, tomber.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-429-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C429'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Utiliser, en situation vécue, les termes adéquats liés : - à l’espace : courir jusqu’à, s’arrêter à, à l’intérieur de, à l’extérieur de, dedans, dehors, au-dessus, en dessous, à côté de ; - au temps : avant, après, pendant que, en même temps que ; - au rythme : lent, rapide.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-410-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C410'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Désigner, nommer au moins cinq éléments du matériel psychomoteur, utilisé en situation vécue. Par exemple : banc, cerceau, cône, élastique, balle, ballon, tapis.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
