insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MAT-M3-440-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C440'), 'maternelle', array['M3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation physique', 'attendu', 'Effectuer des mouvements et des gestes lors de la réalisation d’une activité (par exemple : en ateliers, en circuit) : - marcher, courir, ramper, sauter, grimper, glisser ; - tirer, pousser, lancer, rattraper, shooter à l’aide d’un objet ; - rétablir son équilibre.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
