insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P1-16-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C16'), 'primaire', array['P1']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Adopter, avec l’aide de l’enseignant, une attitude proactive qui prend en considération les risques et les dangers, pour soi et pour les autres, lors de la préparation du poste de travail* et de l’exécution des gestes techniques*, et en recourant notamment aux équipements de protection adéquats.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-17-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C17'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Nommer les fruits et les légumes de saison choisis par l’enseignant.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-18-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C18'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, dans son cadre d’application*, le vocabulaire spécifique aux ustensiles et aux techniques* d’épluchage et de découpe.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-19-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C19'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, dans son cadre d’application*, le vocabulaire spécifique au matériel* et aux techniques* de nettoyage des ustensiles et du plan de travail.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-20-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C20'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Énoncer un protocole de lavage des mains qui garantit la sécurité sanitaire des aliments.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-21-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C21'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'aliment dont éplucher, découper et prélever une quantité.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-22-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C22'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Sur la base d’une recette en images, énoncer les ingrédients, les étapes, la technique* et les ustensiles utilisés dont ceux destinés à prélever des quantités (cuillère à soupe, cuillère à café, pincée ou autre étalon).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-23-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C23'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Se laver les mains en respectant une procédure.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-24-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C24'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Sur la base d’une recette accompagnée d’images et/ou d’une capsule vidéo, préparer, avec l’aide de l’enseignant, un plat simple ou un aliment constitutif d’un plat, en appliquant la technique* appropriée et en utilisant les ustensiles adéquats.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-25-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C25'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Valoriser un plat, avec l’aide de l’enseignant, au travers d’un dressage soigné.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-26-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C26'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Associer des solides préparés par l’enseignant aux objets qu’ils représentent : murs, portes, fenêtres, mobilier.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-26-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C26'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Réaliser, à l’aide de solides proportionnés préparés par l’enseignant, la maquette d’une salle de classe observée in situ.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-27-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C27'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Matérialiser, sur une maquette réalisée, des aménagements de cet espace qui répondent à des besoins liés aux utilisateurs et/ou aux activités.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-27-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C27'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Expliquer en quoi les aménagements proposés répondent aux besoins et tiennent compte des contraintes identifiées.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-1-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C1'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom de matériaux*, de matières* dont papier, carton, corde, bois, plastique, fil métallique, verre, sable.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-2-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C2'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils de mesure dont mètre pliant, mètre roulant.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-3-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C3'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Identifier, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils, de consommables*, de maintien et de fixation dont agrafeuse, agrafe, marteau, clou, pince coupante, pince à bec.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-28-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C28'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Reconnaitre les outils de transformation, en fonction de l’ouvrage* à réaliser par les élèves, dont la scie, le moule, le couteau. Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, les termes dont mesurer, tracer, nouer, serrer, perforer, pincer, clouer, arracher, mouler.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P2-29-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C29'), 'primaire', array['P2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Appliquer des gestes techniques* dont mesurer, contrôler, tracer, nouer, serrer, perforer, pincer, clouer, arracher, mouler.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
