insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-P3-46-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C46'), 'primaire', array['P3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Produire un contenu médiatique simple (ex. : son, image, photo, vidéo, texte).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
