insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-S3-175-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C175'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Au départ d’une étiquette, d’un emballage mentionnant la provenance et le poids ou calibre d’un aliment, poser un choix, en fonction du plat à réaliser, qui limite le cout, le gaspillage et les impacts écologiques (SF, P4).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-S3-175-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C175'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Trier, en autonomie, dans leur cadre de production, les déchets recyclables, compostables, récupérables (SF, P1 à S3).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-S3-175-3', (select id from public.curriculum_item where version = '2022' and code = 'MT-C175'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'Rechercher une information au moyen d’un outil de recherche imposé, en utilisant une bibliothèque appropriée (images, vidéos…), des mots-clés choisis collectivement puis individuellement, des opérateurs et/ou des options avancées, Traduire un logigramme en langage de programmation, le tester, le déboguer, l’optimiser (C, S1-S2).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-S3-175-4', (select id from public.curriculum_item where version = '2022' and code = 'MT-C175'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'L’esprit d’entreprendre suppose de l’initiative, de la créativité, de l’innovation et de', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('MT-S3-176-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C176'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Formation manuelle et technique', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
