insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-86-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C86'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-87-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C87'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'L’esprit d’entreprendre suppose de l’initiative, de la créativité, de l’innovation et de l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-88-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C88'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes.', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-89-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C89'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-89-2', (select id from public.curriculum_item where version = '2022' and code = 'PC-C89'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-90-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C90'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une décou-', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-91-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C91'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'verte du monde extérieur et de l’éventail des possibles qu’il offre en matière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-92-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C92'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités professionnelles, de manière à se forger une vision de l’avenir et à se mettre', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-93-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C93'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('PC-S3-94-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C94'), 'primaire', array['S3']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Identifier-exemplifier la diversité des cultures. (S) Suite aux visites et observations in situ, identifier : - un lieu culturel de son environnement et/ou un spectacle (théâtre, concert, cinéma, chapiteau…) ; - des éléments du patrimoine local ;', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
