insert into public.curriculum_item (code, parent_id, level, grades, tracks, subject, kind, label, source, version) values ('SC-S2-251-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C251'), 'primaire', array['S2']::text[], array['general', 'technique', 'professionnel', 'specialise']::text[], 'Sciences', 'attendu', 'Citer des causes possibles retenues par les scientifiques pour expliquer une extinction massive d’espèces. Utiliser les termes : noyau terrestre, manteau terrestre, écorce terrestre, activité sismique, activité volcanique, sélection naturelle, arbre phylogénétique, espèce, ancêtre commun, extinction massive.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, tracks = excluded.tracks, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
